import type {SessionListOptions, SessionStore} from '../../types/sessionStore.js';

describe('answering list_sessions in the message handler', () => {
  it('lists the connection user\'s sessions with ISO dates, off the per-session lock', async () => {
    const sent: OutgoingMessage[] = [];
    const ws = {send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;
    const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
    const seen: Array<{userId: string | number; options?: SessionListOptions}> = [];
    const store = {
      listFor: (userId: string | number, options?: SessionListOptions) => {
        seen.push({userId, options});
        return [{sessionId: 's2', createdAt: new Date(0), updatedAt: new Date(1000), entryCount: 2}];
      },
    } as unknown as SessionStore;

    await createMessageHandler({} as ChatOrchestrator, store)(ws, session, {type: 'list_sessions', userId: 'u2', limit: 5});

    expect({seen, sent}).toEqual({
      seen: [{userId: 'u1', options: {limit: 5, before: undefined}}],
      sent: [
        {
          type: 'session_list',
          sessions: [
            {sessionId: 's2', createdAt: '1970-01-01T00:00:00.000Z', updatedAt: '1970-01-01T00:00:01.000Z', entryCount: 2},
          ],
        },
      ],
    });
  });
});
